"""Preserve user corrections as distinct, canonical concept briefs."""
import json
from pathlib import Path
ROOT=Path(__file__).resolve().parents[1]
OUT=ROOT/'docs/art/asset-concepts/2026-10-03'
entries=json.loads((OUT/'prompts.json').read_text(encoding='utf-8'))
old=next((e for e in entries if e['id']=='elemental-surtlings'),None)
if old is None:raise SystemExit('This curated run already has distinct elemental pairs; refusing to replace them')
common='Use case: stylized-concept. Dedicated Magenheim Underworld elemental Surtling pair production concept sheet. Adult masculine and feminine full-body front and three-quarter studies, same scale ruler, isolated black silhouettes and body construction detail. Restrained coarse Valheim-painted texture language, neutral grey parchment, readable labels. They are elemental intelligences embodied as humanoids: THE ELEMENT IS THE BODY, not a human wearing elemental armour. Element-specific anatomical mass and proportions, not a recolored generic male/female. One recognizable spirit family and reusable humanoid bone-role/animation contracts do NOT mean identical visible bodies. Coherent connected anatomy and clear joint articulation. Integrated opaque elemental pelvic/chest coverage suitable for ordinary gameplay; no nudity, sexual posing or separate normal human skin. At most two major material families and bounded localized glow. Fine grain in owned texture maps; clear silhouette takes precedence over dense particles. '
profiles={
 'earth':('enormous strongman build: barrel chest, THICK broad waist, huge forearms and hands, deep torso, thick neck, massive thighs and calves, wide planted feet; visibly overwhelming mass, NOT a lean bodybuilder or a V-taper','heavy powerful earth-mother build: tall substantial shoulders, broad hips, strong abdomen, thick weight-bearing legs and arms, generous physical mass, unmistakable strength','interlocking basalt/granite/ore stone masses function as musculature, shallow mineral seams, gravel crown, integrated pelvic stone plates, very restrained mineral glow','slow costly acceleration and heavy weight-settle'),
 'fire':('heroic V-taper, lean muscular torso, powerful defined arms; athletic explosive physique, clearly slimmer than Earth','athletic hourglass with strong shoulders and powerful thighs, balanced muscular motion, never delicate','charcoal-black solidified flame, orange-red heat beneath fissures, obsidian/cinder integrated plates, short male flame crest and streaming female flame plume; no bright full-body fire obscuring anatomy','restless weight shifts and explosive attack poses'),
 'water':('broad swimmer shoulders, long torso, lean strong limbs and narrow waist, fluid continuous curves rather than rock bulk','powerful swimmer build, pronounced hips, smooth long torso and limbs, continuous current lines','nearly black deep-water opaque core, cyan internal caustics, semi-transparent edges, restrained fin-like current sheets at calves/forearms, water-ribbon crowns and compact nacre/shell fittings; NO blue plastic or stone armour body','slow rolling shoulder/hip transfer and drifting currents'),
 'wind':('lithe runner/climber, narrow waist and shoulders, extremely long lean limbs; visibly light compared with every other element','very lean dancer/acrobatic build, compact torso, long arms and legs, lifted heel and light poised stance','pale semi-solid mist core with localized vapor ribbons and dust currents, silhouette visibly light and narrow, streaming gravity-defying crown, thin elemental sash; no electric lightning, no heavy rock plates','quick recovery, current-driven sway and weightless heel lifts'),
 'radiance':('classical heroic sculpture proportions, symmetrical strong chest and limbs, measured idealized athletic strength; neither Earth bulk nor Wind thinness','statuesque regal classical figure, poised symmetry, long balanced proportions and serene authority','translucent alabaster/ivory mineral body with internal white-gold illumination, concentrated pupil-less eyes, broken radiant crown arcs, spare integrated ceremonial plates; no yellow skin or blinding bloom','deliberate symmetrical ceremonial stance and calm controlled movement'),
 'umbral':('tall lean sharply defined and unnaturally elegant, long limbs, angular shoulders and narrow torso; predatory negative-space silhouette','elongated elegantly predatory form with narrow waist and controlled curves, long limbs and poised stalking posture','matte absorptive dark body with opaque shadow masses, localized red recessed eyes, wispy dark crown and sparse integral shadow regalia; NOT a skeleton recolor or person in a black robe. Keep silhouette readable, no full-body transparent shader','quiet measured stalking and unnervingly economical movement')}
new=[]
for element,(male,female,material,motion) in profiles.items():
 name=element.title()+' Surtlings'
 prompt=common+'Title: '+name+' — distinct elemental anatomy. MASCULINE: '+male+'. FEMININE: '+female+'. Elemental surface construction: '+material+'. Motion study: '+motion+'. Include a clearly labeled solid black silhouette comparison of these two builds, not extra elemental variants. No other elements on this sheet. Morphology must remain distinguishable if colors and particles are removed.'
 new.append(dict(id='surtlings-'+element,name=name+' — masculine and feminine',category='Creatures',biome='Underworld elemental',file='surtlings-'+element+'.png',members=[element.title()+' Surtling Masculine',element.title()+' Surtling Feminine'],prompt=prompt,status='planned',supersedes='drafts/elemental-surtlings.png'))
position=entries.index(old);entries[position:position+1]=new
root=next(e for e in entries if e['id']=='rootforged-modular-kit')
root_prompt='Use case: precise-object-edit. Correct this Rootforged reference sheet to preserve its established identity: the structural members MUST be visibly ENTWINED ROOTS, not sawn straight timber or ordinary wooden beams. Replace the square timber bodies of beams, pillars, forked columns, T/Y braces and arch ribs with two or three substantial winding, braiding, fused Worldroot strands; knotty organic curves and obvious root interweaving run through the entire member. Arch ribs remain natural entwined root curves all the way into BOTH aligned feet. Floor is a stable flattened root-lattice walking surface over interwoven root supports whose ends meet adjacent tiles, not regular sawn plank flooring. Stairs use robust flattened root treads and entwined root stringers. Iron bands genuinely bind the root bundles, never erase their organic silhouette. Understone foundation and plinth remain rough stone, do not turn stone into roots. Preserve 2/4/8m family sizes, modular use, symmetric usable attachment endpoints on the 1m/2m grid and measured connection collars: natural curves between deliberate aligned endpoints. Show main silhouettes clearly, no dense spaghetti or hundreds of fine strands. Preserve neutral parchment style, coarse Valheim material language, readable kit labels and assembled bay. Worn fibrous root bark and roots winding around one another are the core identity. Do not make another lumber kit.'
root['refinement_prompt']=root_prompt
(OUT/'prompts.json').write_text(json.dumps(entries,indent=2),encoding='utf-8')
(OUT/'surtling-root-correction-prompts.json').write_text(json.dumps(dict(surtlings=new,rootforged=dict(id=root['id'],file='rootforged-modular-kit--v2.png',prompt=root_prompt)),indent=2),encoding='utf-8')
print('Prepared six anatomically distinct elemental pair sheets and one entwined-root correction')
